"use client";

import { useEffect, useState } from "react";
import { getQuizzes, Quiz } from "@/app/lib/api";
import CreateQuizModal from "./CreateQuizModal";

export default function QuizzesSection() {
  const [quizzes, setQuizzes] = useState<Quiz[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [isModalOpen, setIsModalOpen] = useState(false);

  const fetchQuizzes = async () => {
    try {
      setLoading(true);
      const response = await getQuizzes();
      setQuizzes(response.data);
      setError("");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load quizzes");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchQuizzes();
  }, []);

  if (loading) {
    return (
      <div className="flex items-center justify-center h-full">
        <p className="text-gray-500 dark:text-gray-400">Loading quizzes...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center justify-center h-full">
        <div className="text-red-500 dark:text-red-400">{error}</div>
      </div>
    );
  }

  return (
    <div className="p-6">
      <h2 className="text-2xl font-bold mb-6 text-black dark:text-white">
        Quizzes
      </h2>
      <div className="grid gap-6">
        {quizzes.length === 0 ? (
          <p className="text-gray-500 dark:text-gray-400">No quizzes found.</p>
        ) : (
          quizzes.map((quiz) => (
            <div
              key={quiz._id}
              className="border border-gray-200 dark:border-zinc-700 rounded-lg p-6 hover:bg-gray-50 dark:hover:bg-zinc-800"
            >
              <div className="flex items-start justify-between mb-4">
                <div>
                  <h3 className="text-xl font-bold text-black dark:text-white mb-1">
                    {quiz.quizId}
                  </h3>
                  <p className="text-gray-600 dark:text-gray-400">
                    Tournament: {quiz.tournament}
                  </p>
                </div>
                <span
                  className={`px-3 py-1 rounded-full text-sm font-medium ${
                    quiz.quizStatus === "ENTRYNOTSTARTED"
                      ? "bg-gray-200 text-gray-800 dark:bg-gray-700 dark:text-gray-200"
                      : quiz.quizStatus === "ENTRYSTARTED"
                      ? "bg-blue-200 text-blue-800 dark:bg-blue-900 dark:text-blue-200"
                      : "bg-green-200 text-green-800 dark:bg-green-900 dark:text-green-200"
                  }`}
                >
                  {quiz.quizStatus}
                </span>
              </div>

              {/* Teams */}
              <div className="flex items-center gap-4 mb-4 p-4 bg-gray-50 dark:bg-zinc-800 rounded-lg">
                <div className="flex-1 text-center">
                  <div
                    className="inline-block w-16 h-16 rounded-full mb-2"
                    style={{ backgroundColor: quiz.teamAcolorPrimary }}
                  />
                  <p className="font-semibold text-black dark:text-white">
                    {quiz.teamA}
                  </p>
                </div>
                <span className="text-gray-400 dark:text-gray-500 font-bold">
                  VS
                </span>
                <div className="flex-1 text-center">
                  <div
                    className="inline-block w-16 h-16 rounded-full mb-2"
                    style={{ backgroundColor: quiz.teamBcolorPrimary }}
                  />
                  <p className="font-semibold text-black dark:text-white">
                    {quiz.teamB}
                  </p>
                </div>
              </div>

              {/* Quiz Details */}
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4 text-sm">
                <div>
                  <p className="text-gray-500 dark:text-gray-400 mb-1">
                    Entry Start
                  </p>
                  <p className="text-black dark:text-white">
                    {new Date(quiz.entryStartTime).toLocaleString()}
                  </p>
                </div>
                <div>
                  <p className="text-gray-500 dark:text-gray-400 mb-1">
                    Entry Stop
                  </p>
                  <p className="text-black dark:text-white">
                    {new Date(quiz.entryStopTime).toLocaleString()}
                  </p>
                </div>
                <div>
                  <p className="text-gray-500 dark:text-gray-400 mb-1">
                    Questions
                  </p>
                  <p className="text-black dark:text-white">
                    {quiz.questionsArray?.length || 0}
                  </p>
                </div>
                <div>
                  <p className="text-gray-500 dark:text-gray-400 mb-1">
                    Submissions
                  </p>
                  <p className="text-black dark:text-white">
                    {quiz.responseSubmittedByUsers?.length || 0}
                  </p>
                </div>
              </div>

              {/* Questions */}
              {quiz.questionsArray && quiz.questionsArray.length > 0 && (
                <div className="mt-4 border-t border-gray-200 dark:border-zinc-700 pt-4">
                  <h4 className="font-semibold text-black dark:text-white mb-3">
                    Questions ({quiz.questionsArray.length})
                  </h4>
                  <div className="space-y-3">
                    {quiz.questionsArray.map((question, idx) => (
                      <div
                        key={question._id || idx}
                        className="p-3 bg-gray-50 dark:bg-zinc-800 rounded-lg"
                      >
                        <div className="flex items-start justify-between mb-2">
                          <p className="font-medium text-black dark:text-white">
                            Q{question.questionNumber}: {question.questionText}
                          </p>
                          <span className="text-sm text-gray-500 dark:text-gray-400">
                            {question.points} pts
                          </span>
                        </div>
                        <div className="grid grid-cols-2 gap-2 mt-2">
                          {question.options?.map((option, optIdx) => (
                            <div
                              key={optIdx}
                              className={`text-sm p-2 rounded ${
                                option === question.correctAnswer
                                  ? "bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200 font-medium"
                                  : "bg-white dark:bg-zinc-700 text-gray-700 dark:text-gray-300"
                              }`}
                            >
                              {option}
                              {option === question.correctAnswer && (
                                <span className="ml-2">✓</span>
                              )}
                            </div>
                          ))}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Created By */}
              <div className="mt-4 pt-4 border-t border-gray-200 dark:border-zinc-700 text-sm">
                <p className="text-gray-500 dark:text-gray-400">
                  Created by: {quiz.createdByUserData?.email} (
                  {quiz.createdByUserData?.userType})
                </p>
                <p className="text-gray-500 dark:text-gray-400">
                  Visibility: {quiz.isVisible ? "Visible" : "Hidden"}
                </p>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}
